 function scanning(){if(opening.active){openingAct();return;}if(relayReach()){clearDrive();ExoFieldStory.openRelay();return;}if(mode!=='world')return;if(terrain.active&&!ExoWorld.portal(unit)&&!ExoWorld.cave){Exo.terrainProbe();return;}if(combat.trial){combat.message='这里是战斗练习区。回到自由探索后，就能扫描地标并保存发现。';document.getElementById('exo-radio').textContent=combat.message;return;}if(fireCourse.active){Exo.courseCycle();return;}if(interaction()||storyInteractionNear()||lampNear()||(typeof ExoTrainingGround!=='undefined'&&!ExoWorld.cave&&ExoTrainingGround.near(unit))||ExoGreenTrail.near(unit)||ExoWorld.portal(unit)||ExoWorld.cave||ExoWorld.buildingPortal?.(unit)){interact();return}if(ExoCanyonV2.inZone(unit.x,unit.y)){document.getElementById('exo-radio').textContent='这里是 K–09 旧河谷。沿青绿灯走向撤离机库；靠近灯箱或路边遗留的物件，按 E 查看。';return;}scan={x:unit.x,y:unit.y,time:performance.now()};sound(720,.6);const near=M.sites.map(s=>({s,d:Math.hypot(s.x-unit.x,s.y-unit.y)})).sort((a,b)=>a.d-b.d)[0];document.getElementById('exo-radio').textContent=near.d<195?'这是旧测绘信标。先帮老林守住维修间，再来接通远行的地图。':'最近的测绘信标：'+near.s.name+'，约 '+Math.round(near.d/18)+' m。打开地图可沿路前往。';}
