 addEventListener('resize',resize);addEventListener('blur',()=>{keys.clear();firing=false;viewPointer=null;input={x:0,y:0};boost=false;verticalInput=0;target=null;joyId=null;const knob=document.getElementById('exo-knob');if(knob)knob.style.transform='translate(0,0)'});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();firing=false;viewPointer=null;input={x:0,y:0};boost=false;target=null}});addEventListener('keydown',e=>{if(mode!=='world'||document.getElementById('modal')?.open||ExoLampWiring.open)return;const k=e.key.toLowerCase();if(opening.locked&&k!=='escape'){if(k==='e'&&!e.repeat){e.preventDefault();openingAct();}return;}if(opening.active&&['f','j','k','v'].includes(k))return;if(surveyPanel?.isConnected&&['q','r','e','escape'].includes(k)&&!e.target?.closest?.('input,button')){e.preventDefault();if(!e.repeat){if(k==='escape')closeSurvey();else if(k==='e'){if(surveyId==='refuge')refugeDeliver();else if(surveySession)surveyVerify();else surveySample();}else surveyNudge(k==='q'?-.5:.5);}return;}if(ExoFieldStory.panelOpen&&['q','r','e'].includes(k)&&!e.target?.closest?.('input,button')){e.preventDefault();if(!e.repeat){if(k==='e')relayTransmit();else relayNudge(k==='q'?-5:5);}return;}if(k!=='escape'&&e.target?.closest?.('input,select,textarea,button,summary,[contenteditable="true"]'))return;if(k==='escape'||k==='m'){e.preventDefault();if(!e.repeat)hub(k==='m'?'map':hubSection);return;}if(k==='g'){e.preventDefault();if(!e.repeat)Exo.toggleView();return;}if(['q','r','t','w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','e','f','j','k','v','c','shift'].includes(k)){e.preventDefault();if(fireCourse.active&&['q','r','t'].includes(k)){if(k==='t'){if(!e.repeat)Exo.courseCycle()}else Exo.courseTrim(fireCourse.trim+(k==='q'?-1:1));return}if(k==='t'){if(!e.repeat)Exo.cycleTarget();return}else if(k==='v'){if(!e.repeat)flightToggle()}else if(k==='j'||k==='k'){if(!e.repeat)weapon(k==='j'?'saber':'missiles')}else if(k==='e'){if(!e.repeat)scanning()}else keys.add(k)}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
 function journal(tab='journey'){hub(tab==='upgrades'?'mech':['regions','records'].includes(tab)?'archive':'journey',tab);}
 function trackJourney(){
  const o=journey.objective();if(o.finished){journal('records');return;}
  if(o.action.kind==='lesson'){closeModal();if(o.action.id===1)Exo.firstMission();else Exo.terrainPanel();return;}
  if(ExoWorld.interior&&o.action.kind==='facility'&&ExoWorld.interior.structure.id===o.action.id){Exo.travel();return;}
  const p=journey.targetFor(o.action);if(!p){journal();return;}
  const underground=!!ExoWorld.cave;
  terminal('journey','<div class="exp-journal"><div class="exp-eyebrow">第一卷 / 实地调查</div><h2>'+p.name+'</h2><p>'+o.detail+'</p><p class="exp-hint">X '+Math.round(p.x)+' / Y '+Math.round(p.y)+' · 地表坐标</p><p>'+(underground?'你现在在地下。先打开地图找到出口，回到地表后就能设置路线。':'路线会先带你走上道路。最后一段只指向目的地，需要自己绕过岩壁和建筑；到了开阔处也可以起飞。')+'</p><div class="fc-buttons">'+(!underground?'<button class="primary" onclick="Exo.navigateStory()">沿道路导航</button>':'<button onclick="Exo.travel()">查看地下地图</button>')+(o.action.kind==='facility'?'<button onclick="closeModal();Exo.visitFacility(\''+o.action.id+'\')">直接到达设施入口</button>':'')+'<button onclick="Exo.journal()">返回当前任务</button></div></div>');
 }
 function navigateStory(){if(trialBattle)leaveCave();const p=journey.targetFor(journey.objective().action);if(!p||ExoWorld.cave)return;const route=ExoWorld.navigatePoint(unit,p);if(!route)return;clearDrive();fireCourse.active=false;terrain.active=false;fireCourse.uiPending=null;terrain.uiPending=null;terrain.probe=null;closeModal();world();combat.message='路线已标好：'+p.name+'。最后一段需要自己避开岩壁和建筑。';document.getElementById('exo-radio').textContent=combat.message;}
 function campaign(){observeCampaign();terminal('journey',campaignState.panel(),'回声之下 · 第一幕');}
 function storyMoment(){
  if(opening.active){closeModal();if(!hasSortie)startCampaign();else openingAct();return;}
  observeCampaign();const o=campaignState.objective();if(o.action!=='acknowledge'){trackCampaign();return;}
  clearDrive();closeModal();if(campaignState.award(o.event)){
   ExoFieldStory.say(o.id);syncUpgrades();campaignState.checkpoint(unit);
   if(o.id==='stabilizer'){unit.energy=100;combat.hp=Math.min(100,combat.hp+20);}
   campaignTracked=true;guideCampaign();campaignState.updateHUD();
  }
 }
 const objectEscape=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 function nearbyLamp(id){
  const item=[...ExoLampRepair.all(),...ExoGuidance.waylights(ExoWorld)].find(p=>p.id===id);
  return mode==='world'&&!combat.down&&!combat.trial&&!fireCourse.active&&!terrain.active&&item&&ExoGuidance.distance(unit,item)<=ExoGuidance.REACH&&ExoGuidance.clear(unit,item,ExoWorld)?item:null;
 }
 function inspectLamp(value,feedback='',confirm=false){
  const lamp=nearbyLamp(typeof value==='string'?value:value?.id);if(!lamp)return;clearDrive();
  const id=lamp.id,isMemory=lamp.kind==='spare',isCache=lamp.kind==='cache',isWay=lamp.kind==='waylight';
  const firstReading=isMemory&&!journey.trailEarned.includes(id);
  if(isMemory){journey.scanTrail(unit,expeditionActive());journey.dismiss();observeCampaign();syncUpgrades();const nav=ExoWorld.navigation(unit);if(campaignTracked&&(!nav||nav.target?.story))guideCampaign();campaignState.updateHUD();}
  const observations={
   'trail:k09:1':'灯箱接着一块独立电池。车辙尽头的转运单被油污划过：“设备优先”改成了“孩子、伤员、不能自己走的人”。最后一辆车运走了人，留下了矿石。',
   'trail:k09:2':'工具散落在检修桩脚下。值守器的残音说，他要留下来换两盏灯。工单上的签字比末班车晚了十九分钟；录音没说他有没有追上车。',
   'trail:k09:3':'补给箱写着“给落单的人留一份”。新电池的批次晚于撤离日，壶底还有烧过的痕迹——灾难以后，有人沿着这条路回来过。'
  };
  if(firstReading&&!feedback){ExoFieldStory.cue('陆寻',id==='trail:k09:1'?'转运单被改过。最后一辆车没有装矿石，装的是孩子和伤员。':id==='trail:k09:2'?'他留下来换灯，错过了末班车。后来呢？':'有人回来过。还给落单的人留下了电池。');closeModal();return;}
  const level=isWay?1:ExoLampRepair.level(lamp),cells=ExoLampRepair.summary().cells,drawn=ExoLampRepair.state.drawn[id]||0;
  const status=isCache?(ExoLampRepair.taken(id)?'补给已取出':'发现应急电池'):level===1?'灯光稳定':level>0?'灯光微弱':'灯已熄灭';
  const copy=observations[id]||(isCache?'检修包被风吹倒，里面的电池仍有余量。取出后，可以给断电的路灯接上电源。':isWay?(lamp.side?'旧灯牌上画着一条绕回主路的小径。这里通往沿途遗物，之后还能回到青灯归路。':'磨损的灯牌指向前方。青绿灯串起主路；路面的双折线是机甲投出的当前路线。'):level===1?'接线盒已经合拢，灯头稳定地照着路面。你修好的灯会一直留在这条路上。':'灯罩有裂痕，电池仓已经空了。装入一块电池，再把断开的线接回灯头，就能让它重新亮起来。');
  let actions='';
  if(isCache)actions=ExoLampRepair.taken(id)?'<span>这个补给点已经搜过了。</span>':`<button class="primary" onclick="Exo.lampAction('${id}','take')">取出应急电池</button>`;
  else if(lamp.kind==='broken'&&level===0)actions=`<button class="primary" ${cells?'':'disabled'} onclick="Exo.lampAction('${id}','repair')">装入电池并打开接线盒</button>${cells?'':'<small>还缺一块电池。沿路找翻倒的检修包或补给箱。</small>'}`;
  else if(isMemory)actions=`<details class="exo-lamp-battery"><summary>电池仓 · ${2-drawn} / 2 块</summary><p>取走一块会让灯变暗；取走最后一块会熄灯。也可以把电池装回去。</p><div class="exo-object-actions"><button ${drawn>=2?'disabled':''} onclick="Exo.lampAction('${id}','take')">${confirm?'确认取走最后一块':'取一块备用电池'}</button><button ${drawn>0&&cells?'':'disabled'} onclick="Exo.lampAction('${id}','return')">装回一块电池</button></div></details>`;
  const o=campaignState.objective();
  modal(lamp.name,`<section class="exo-object-panel exo-lamp-panel"><span class="exo-object-tag">${isMemory?'路边遗物 · 已记入日记':isWay?'维护路标':'现场检修'}</span><h2>${objectEscape(lamp.name)}</h2><div class="exo-lamp-status"><i data-power="${level}"></i><strong>${status}</strong><span>随身电池 ${cells}</span></div><p class="exo-object-observation">${copy}</p><p class="exo-lamp-feedback" role="status">${objectEscape(feedback)}</p><div class="exo-object-actions">${actions}</div><div class="exo-lamp-next"><small>接下来</small><strong>${objectEscape(ExoGuidance.name(o))}</strong><p>${o.id==='lamps'?'这盏灯已经指向归路。其他遗物可以稍后再找。':o.finished?'沿主路继续探索。':'沿青灯前行；支路可以随时再来。'}</p><button class="primary" onclick="Exo.trackCampaign()">继续沿主路走</button><button onclick="closeModal()">收起</button></div></section>`);
  if(confirm){const details=document.querySelector('.exo-lamp-battery');if(details)details.open=true;}
 }
 function lampAction(id,choice){
  const lamp=nearbyLamp(id);if(!lamp||!['take','return','repair'].includes(choice))return;
  if(choice==='repair'){if(lamp.kind!=='broken')return;closeModal();lampAct(lamp);return;}
  if(lamp.kind!=='spare'&&lamp.kind!=='cache')return;
  const r=ExoLampRepair.act(lamp,Date.now(),choice);lampSay(r,lamp);inspectLamp(lamp,r.message,!!r.confirm);
 }
 function startCampaign(){
  leaveCave();clearDrive();M.resetFlight(unit);ExoWorld.cancelRoute();fireCourse.active=false;terrain.active=false;fireCourse.uiPending=null;terrain.uiPending=null;terrain.probe=null;combat=surfaceCombat;combat.hp=100;combat.down=0;combat.invulnerable=5;combat.bolts=[];combat.hazards=[];ExoSandbox.clearWeapons(combat);
  const p=campaignState.state.checkpoint||ExoTrainingGround.campaign.start;Object.assign(unit,{x:p.x,y:p.y,vx:0,vy:0,angle:p.angle||0,energy:100});camera.yaw=-unit.angle;camera.pitch=.20;camera.distance=560;campaignState.start();campaignTracked=true;if(campaignState.objective().id==='crash'){openingView=camera.firstPerson;if(opening.start(unit)){camera.firstPerson=true;camera.pitch=.08;}else campaignState.award('crash-read');}world();observeCampaign();guideCampaign();campaignState.updateHUD();
 }
 function openingAct(){
  if(!opening.active)return;const result=opening.act();clearDrive();if(result==='power'){sound(320,.3);setTimeout(()=>{if(opening.active)sound(95,.09);},700);setTimeout(()=>{if(opening.active)sound(95,.09);},1040);ExoFieldStory.say('power',!opening.replay);}if(result==='release')sound(100,.4);opening.draw(document.getElementById('exo-field'));document.getElementById('exo-world')?.focus({preventScroll:true});
 }
 function finishOpening(){
  clearDrive();camera.firstPerson=openingView;
  if(replaySnapshot){Object.assign(unit,replaySnapshot.unit);Object.assign(camera,replaySnapshot.camera);combat.hp=replaySnapshot.hp;camera.x=unit.x;camera.y=unit.y;camera.z=ExoWorld.elevation(unit.x,unit.y);checkpointAt=performance.now();replaySnapshot=null;}
  else {campaignState.award('crash-read');campaignState.checkpoint(unit);ExoFieldStory.say('escaped');}
  document.getElementById('exo-field')?.classList.toggle('fpv',camera.firstPerson);Exo3D.resetOrbit(camera);syncUpgrades();campaignTracked=true;guideCampaign();campaignState.updateHUD();
 }
 function replayOpening(){
  if(!campaignState.state.done.includes('crash')){startCampaign();return;}
  if(opening.active){closeModal();world();return;}
  const p=hasSortie&&!ExoWorld.cave&&!ExoWorld.interior?{...unit}:{...campaignState.state.checkpoint||ExoTrainingGround.campaign.start,energy:100};
  replaySnapshot={unit:p,camera:{...camera},hp:combat.hp};openingView=camera.firstPerson;
  leaveCave();if(ExoWorld.interior)leaveFacility();clearDrive();M.resetFlight(unit);fireCourse.active=false;terrain.active=false;combat=surfaceCombat;combat.invulnerable=60;ExoWorld.cancelRoute();
  Object.assign(unit,{...ExoTrainingGround.campaign.start,vx:0,vy:0,energy:100});camera.firstPerson=true;camera.yaw=-unit.angle;camera.pitch=.08;opening.start(unit,true);world();
 }
 function relayReach(){return mode==='world'&&campaignState.state.finished&&!opening.active&&!combat.down&&!fireCourse.active&&!ExoWorld.cave&&!ExoWorld.interior&&!unit.flight&&Math.hypot(unit.x-ExoFieldStory.relay.x,unit.y-ExoFieldStory.relay.y)<=(ExoFieldStory.panelOpen?230:ExoFieldStory.relay.radius);}
 function relayPower(source){
  if(!relayReach()||!ExoFieldStory.panelOpen)return;const s=ExoFieldStory.state;
  if(source==='battery'&&!s.relayBattery){if(!ExoLampRepair.useCell()){ExoFieldStory.cue('AEGIS','没有备用电池。机甲还能临时供电。');return;}ExoFieldStory.power(true);}
  else if(source==='mech'&&!s.relayPower){if(unit.energy<45){ExoFieldStory.cue('AEGIS','能源不足。等机甲恢复到 45，再试一次。');return;}unit.energy-=45;ExoFieldStory.power(false);}
 }
 function relayTurn(value){if(relayReach()&&ExoFieldStory.panelOpen&&Number.isFinite(value))ExoFieldStory.turn(value);}
