  const s=ExoSurvey.sites.find(p=>surveyReach(p));return s?{kind:'survey',id:s.id,point:s,label:ExoSurvey.calibrated(s.id)?'查看信标与检修柜':'校准'+s.name,detail:'测绘台 · 修正旧地图',priority:0}:null;
